insert into public.products (id, sku, slug, name, short_description, description, category_id, brand_id, price, promo_price, unit, unit_label, min_qty, qty_step, stock, min_stock, weight_kg, length_cm, width_cm, height_cm, specs, is_featured, sold_count, promo_ends_at) values
  ('a0000000-0000-4000-8000-000000000001', 'CIM-CPII-50', 'cimento-cp-ii-f-32-votorantim-50kg', 'Cimento CP II-F-32 Votorantim 50 kg', 'Cimento Portland composto, ideal para concreto, reboco, contrapiso e assentamento.', 'O Cimento CP II-F-32 é o mais versátil da obra: indicado para concretos estruturais, argamassas de assentamento e revestimento, contrapisos e pré-moldados. Armazene em local seco, sobre estrados e em pilhas de até 10 sacos.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000003', 38.9, 34.9, 'saco'::public.sale_unit, 'saco 50 kg', 1, 1, 420, 60, 50, 60, 40, 12, '{"Tipo":"CP II-F-32","Peso":"50 kg","Norma":"NBR 16697","Validade":"90 dias"}'::jsonb, true, 1840, now() + interval '6 days'),
  ('a0000000-0000-4000-8000-000000000002', 'CIM-CPV-50', 'cimento-cp-v-ari-votorantim-50kg', 'Cimento CP V-ARI Votorantim 50 kg', 'Alta resistência inicial: desforma rápida para pré-moldados e estruturas.', 'Cimento de alta resistência inicial (ARI), indicado para pré-fabricados, artefatos de concreto e situações em que a desforma rápida é necessária.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000003', 44.9, null, 'saco'::public.sale_unit, 'saco 50 kg', 1, 1, 180, 30, 50, 60, 40, 12, '{"Tipo":"CP V-ARI","Peso":"50 kg","Norma":"NBR 16697"}'::jsonb, false, 620, null),
  ('a0000000-0000-4000-8000-000000000003', 'ARG-ACIII-20', 'argamassa-ac-iii-quartzolit-20kg', 'Argamassa AC-III Cinza Quartzolit 20 kg', 'Para porcelanatos e peças grandes em áreas internas e externas.', 'Argamassa colante tipo AC-III de alta aderência, indicada para assentamento de porcelanatos, peças de grande formato, fachadas e piscinas. Rendimento aproximado de 4 a 5 kg/m² em dupla colagem.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000006', 34.9, 29.9, 'saco'::public.sale_unit, 'saco 20 kg', 1, 1, 260, 40, 20, 45, 30, 10, '{"Tipo":"AC-III","Cor":"Cinza","Peso":"20 kg","Rendimento":"4 a 5 kg/m²","Tempo em aberto":"30 min"}'::jsonb, true, 1210, now() + interval '6 days'),
  ('a0000000-0000-4000-8000-000000000004', 'ARG-ACI-20', 'argamassa-ac-i-quartzolit-20kg', 'Argamassa AC-I Interno Quartzolit 20 kg', 'Para cerâmicas em pisos e paredes de áreas internas.', 'Argamassa colante AC-I para assentamento de cerâmicas em áreas internas. Fácil preparo, basta adicionar água.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000006', 14.9, null, 'saco'::public.sale_unit, 'saco 20 kg', 1, 1, 310, 40, 20, 45, 30, 10, '{"Tipo":"AC-I","Uso":"Interno","Peso":"20 kg","Rendimento":"4 a 5 kg/m²"}'::jsonb, false, 980, null),
  ('a0000000-0000-4000-8000-000000000005', 'ARG-ASSENT-20', 'argamassa-assentamento-quartzolit-20kg', 'Argamassa de Assentamento Quartzolit 20 kg', 'Pronta para assentar blocos cerâmicos e de concreto.', 'Argamassa industrializada para assentamento de alvenaria de vedação. Dispensa cal e areia: mais produtividade e menos desperdício no canteiro.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000006', 19.9, null, 'saco'::public.sale_unit, 'saco 20 kg', 1, 1, 140, 30, 20, 45, 30, 10, '{"Uso":"Assentamento de alvenaria","Peso":"20 kg","Rendimento":"aprox. 10 kg/m² (bloco 9 cm)"}'::jsonb, false, 410, null),
  ('a0000000-0000-4000-8000-000000000006', 'CAL-CHIII-20', 'cal-hidratada-ch-iii-20kg', 'Cal Hidratada CH-III 20 kg', 'Melhora a trabalhabilidade de rebocos e argamassas.', 'Cal hidratada CH-III para argamassas de assentamento e revestimento, proporcionando maior plasticidade e retenção de água.', '00000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000003', 16.9, null, 'saco'::public.sale_unit, 'saco 20 kg', 1, 1, 95, 20, 20, 45, 30, 10, '{"Tipo":"CH-III","Peso":"20 kg"}'::jsonb, false, 350, null),
